Input: {"question": "When was Senator Bloomer born?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0366-85f85cb2887c:d00", "start": 0, "end": 6, "text": "Asa S."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0366-85f85cb2887c:d00", "start": 7, "end": 21, "text": "Bloomer Asa S."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0366-85f85cb2887c:d00", "start": 22, "end": 210, "text": "Bloomer (August 15, 1891 – February 21, 1963) was a Vermont politician and lawyer who served as Speaker of the Vermont House of Representatives and President Pro Tem of the Vermont Senate."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0366-85f85cb2887c:d00", "start": 211, "end": 289, "text": "Asa Schoonmaker \"Ace\" Bloomer was born in Proctor, Vermont on August 15, 1891."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0366-85f85cb2887c:d00", "start": 290, "end": 442, "text": "He graduated from the University of Vermont in 1913 and received a law degree from Yale Law School in 1916, afterwards practicing law in Rutland County."}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0366-85f85cb2887c:d00", "start": 443, "end": 544, "text": "He enlisted in the Army for World War I and received a commission as a Second Lieutenant of Aviation."}, "D1S7": {"document_number": 1, "doc_id": "ramdocs-0366-85f85cb2887c:d00", "start": 545, "end": 577, "text": "Bloomer served in Nebraska, Ohio"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0366-85f85cb2887c:d01", "start": 0, "end": 7, "text": "John H."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0366-85f85cb2887c:d01", "start": 8, "end": 23, "text": "Bloomer John H."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0366-85f85cb2887c:d01", "start": 24, "end": 162, "text": "Bloomer (September 14, 1930 – January 10, 1995) was a Vermont attorney and politician who served as President of the Vermont State Senate."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0366-85f85cb2887c:d0