": 3, "doc_id": "ramdocs-0366-85f85cb2887c:d02", "start": 387, "end": 507, "text": "In 1947 Bloomer received his law degree from Boston University School of Law 1948, afterwards practicing law in Rutland."}, "D3S8": {"document_number": 3, "doc_id": "ramdocs-0366-85f85cb2887c:d02", "start": 508, "end": 570, "text": "A Republican, in 1963 Bloomer was appointed to the seat in the"}}, "original_cards": [{"doc_id": "ramdocs-0366-85f85cb2887c:d00", "card_id": "ramdocs-0366-85f85cb2887c:d00:c0", "entity": "Senator Bloomer", "scope": "Birth date", "claim": "Asa Schoonmaker \"Ace\" Bloomer was born in Proctor, Vermont on August 15, 1891.", "answer": "August 15, 1891", "quote": "Asa Schoonmaker \"Ace\" Bloomer was born in Proctor, Vermont on August 15, 1891.", "original_document_number": 1}, {"doc_id": "ramdocs-0366-85f85cb2887c:d01", "card_id": "ramdocs-0366-85f85cb2887c:d01:c0", "entity": "Senator Bloomer", "scope": "Birth date", "claim": "John Henry Bloomer was born in Rutland on September 14, 1930.", "answer": "September 14, 1930", "quote": "John Henry Bloomer was born in Rutland on September 14, 1930.", "original_document_number": 2}, {"doc_id": "ramdocs-0366-85f85cb2887c:d02", "card_id": "ramdocs-0366-85f85cb2887c:d02:c0", "entity": "Senator Bloomer", "scope": "Birth date", "claim": "Robert Asa Bloomer was born in Proctor, Vermont on November 13, 1921.", "answer": "November 13, 1921", "quote": "Robert Asa Bloomer was born in Proctor, Vermont on November 13, 1921.", "original_document_number": 3}], "current_answers": ["August 15, 1891", "September 14, 1930", "November 13, 1921"], "candidate_answers": [{"candidate_id": "R0", "answer": "August 15, 1891", "origin": "initial"}, {"candidate_id": "R1", "answer": "September 14, 1930", "origin": "initial"}, {"candidate_id": "R2", "answer": "November 13, 1921", "origin": "initial"}]}
